type Invoice = {
  id: string;
  number: string;
  clientName: string;
  amountCents: number;
  currency: string;
  status: string;
  issuedAt: string;
  dueAt: string;
};
type Page = { data: Invoice[]; nextCursor: string | null };

async function fetchAll(from: string, to: string): Promise<Invoice[]> {
  const out: Invoice[] = [];
  let cursor: string | null = null;
  do {
    const params: Record<string, string> = { from, to, limit: '200' };
    if (cursor) params.cursor = cursor;
    const page: Page = await apiGet<Page>('/v1/invoices', params);
    out.push(...page.data);
    cursor = page.nextCursor;
  } while (cursor);
  return out;
}

export const invoicesExport = new Command('export')
  .description('Export invoices in a date range')
  .requiredOption('--from <date>', 'start date, YYYY-MM-DD')
  .requiredOption('--to <date>', 'end date, YYYY-MM-DD')
  .addOption(new Option('--format <format>', 'output format').choices(['csv', 'json']).default('csv'))
  .option('--out <file>', 'write to a file instead of stdout')
  .action(async (opts: { from: string; to: string; format: 'csv' | 'json'; out?: string }) => {
    const rows = await fetchAll(opts.from, opts.to);
    const body = opts.format === 'csv' ? toCsv(rows) : JSON.stringify(rows, null, 2) + '\n';
    if (opts.out) {
      await writeFile(opts.out, body);
      process.stderr.write(`wrote ${rows.length} invoices to ${opts.out}\n`);
    } else {
      process.stdout.write(body);
    }
  });

